function loadComponent(filePath, elementId) {
    if (!filePath) return;
    fetch(filePath)
    .then(response => {
        if (!response.ok) throw new Error("ไม่พบไฟล์ " + filePath);
        return response.text();
    })
    .then(data => {
        document.getElementById(elementId).innerHTML = data;
    })
    .catch(error => console.error(error));
}

document.addEventListener("DOMContentLoaded", function() {
    loadComponent("/components/header.html", "header-placeholder");
    loadComponent("/components/footer.html", "footer-placeholder");

    // โหลด sidebar ตาม data-sidebar attribute
    const sidebarFile = document.body.getAttribute("data-sidebar");
    if (sidebarFile) {
        // สำหรับ lessons sidebar ใช้ id "sidebar"
        // สำหรับ examples/exercises ใช้ id "ex_sidebar"
        const elementId = sidebarFile.includes("lessons") ? "sidebar" : "ex_sidebar";
        loadComponent(sidebarFile, elementId);
    }
});
